<?php require "../config.php";if(empty($_SESSION["admin"])){header("Location: login.php");exit;}if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$pdo->prepare("INSERT INTO departments(name,contact) VALUES(?,?)");$s->execute([$_POST["name"],$_POST["contact"]]);}$rows=$pdo->query("SELECT * FROM departments ORDER BY id DESC")->fetchAll(PDO::FETCH_ASSOC);?><!doctype html><html><head><title>Departments</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="container"><h2>Manage Emergency Departments</h2><form class="panel" method="post"><input name="name" placeholder="Department name" required><input name="contact" placeholder="Contact number" required><button class="btn">Add Department</button></form><br><table class="table"><tr><th>Name</th><th>Contact</th></tr><?php foreach($rows as $r):?><tr><td><?=$r["name"]?></td><td><?=$r["contact"]?></td></tr><?php endforeach;?></table><p><a href="dashboard.php">Dashboard</a></p></div></body></html>